import{_ as i,o as a,c as t,a2 as s}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Day 10: Git Repositories & Source Patching","description":"","frontmatter":{},"headers":[],"relativePath":"day10-git-repositories-and-source-patching.md","filePath":"day10-git-repositories-and-source-patching.md"}'),o={name:"day10-git-repositories-and-source-patching.md"};function l(n,e,c,h,r,d){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="day-10-git-repositories-source-patching" tabindex="-1">Day 10: Git Repositories &amp; Source Patching <a class="header-anchor" href="#day-10-git-repositories-source-patching" aria-label="Permalink to &quot;Day 10: Git Repositories &amp; Source Patching&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Use the <code>git://</code> fetcher to pull source code directly from Git repositories</li><li>Lock recipe versions using the <code>SRCREV</code> variable</li><li>Generate standard Git <code>.patch</code> files</li><li>Apply patches automatically during the <code>do_patch</code> task using <code>SRC_URI</code></li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day9-build-logs-debugging-makefiles.html">Day 9: Build Logs, Debugging &amp; Makefiles</a></li></ul></div><hr><h2 id="_1-fetching-source-code-from-git" tabindex="-1">1. Fetching Source Code from Git <a class="header-anchor" href="#_1-fetching-source-code-from-git" aria-label="Permalink to &quot;1. Fetching Source Code from Git&quot;">​</a></h2><p>While fetching <code>.tar.gz</code> files over HTTP/HTTPS is common, modern development relies heavily on Git. BitBake has a dedicated <code>git://</code> fetcher module designed to handle Git repositories efficiently.</p><h3 id="basic-git-recipe-example" tabindex="-1">Basic Git Recipe Example <a class="header-anchor" href="#basic-git-recipe-example" aria-label="Permalink to &quot;Basic Git Recipe Example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;An application fetched from GitHub&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LICENSE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LIC_FILES_CHKSUM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Use git:// protocol. </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Add protocol=https to fetch over HTTPS port 443 (fixes corporate firewall issues).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. branch=main ensures we are looking at the correct branch.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;git://github.com/torvalds/linux.git;protocol=https;branch=master&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SRCREV defines the EXACT Git commit hash to checkout. </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Never use &quot;\${AUTOREV}&quot; in production recipes, as it breaks reproducibility!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRCREV</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;c08dd3c9bd6ebc168ceb27131eb6f658399a9a5a&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># When using git://, the source unpacks into a subdirectory called &#39;git&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WORKDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/git&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    oe_runmake</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="git-fetcher-parameters" tabindex="-1">Git Fetcher Parameters <a class="header-anchor" href="#git-fetcher-parameters" aria-label="Permalink to &quot;Git Fetcher Parameters&quot;">​</a></h3><ul><li><code>protocol=https</code>: (Recommended) Fetches over HTTPS. <code>protocol=ssh</code> is required for private repositories.</li><li><code>branch=develop</code>: Specifies the branch to checkout. Defaults to <code>master</code>.</li><li><code>tag=v1.0</code>: Check out a specific release tag.</li></ul><div class="warning custom-block"><p class="custom-block-title">REPRODUCIBILITY</p><p>Yocto is designed to produce the exact same binary output every time you build it. If you use <code>SRCREV = &quot;\${AUTOREV}&quot;</code>, BitBake will reach out to GitHub on every build to find the latest commit. This means a build done tomorrow might yield a different binary than a build done today. <strong>Always hardcode the exact 40-character <code>SRCREV</code> hash in production recipes.</strong></p></div><hr><h2 id="_2-source-code-patching" tabindex="-1">2. Source Code Patching <a class="header-anchor" href="#_2-source-code-patching" aria-label="Permalink to &quot;2. Source Code Patching&quot;">​</a></h2><p>In embedded Linux, you rarely use upstream open-source code exactly as it is. You often need to fix a bug, backport a security patch, or modify a configuration specifically for your hardware.</p><p>Instead of maintaining a massive fork of an entire project (like the Linux kernel) just to change one line of C code, Yocto uses a <strong>patching system</strong>. You download the pristine upstream code, and BitBake applies your custom patches automatically before compiling.</p><h3 id="step-1-generate-a-patch-file" tabindex="-1">Step 1: Generate a Patch File <a class="header-anchor" href="#step-1-generate-a-patch-file" aria-label="Permalink to &quot;Step 1: Generate a Patch File&quot;">​</a></h3><p>Let&#39;s assume we want to patch our <code>helloworld.c</code> from Day 8 to say &quot;Hello from a Patched Yocto!&quot;.</p><ol><li>Go to your source code directory.</li><li>Initialize a local git repository (if it isn&#39;t one already).</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helloworld.c</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Initial pristine code&quot;</span></span></code></pre></div><ol start="3"><li>Make your desired change to <code>helloworld.c</code>.</li><li>Commit the change.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Change greeting text&quot;</span></span></code></pre></div><ol start="5"><li>Generate a standard unified patch file using <code>git format-patch</code>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format-patch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This generates a file named: 0001-Change-greeting-text.patch</span></span></code></pre></div><h3 id="step-2-add-the-patch-to-the-recipe" tabindex="-1">Step 2: Add the Patch to the Recipe <a class="header-anchor" href="#step-2-add-the-patch-to-the-recipe" aria-label="Permalink to &quot;Step 2: Add the Patch to the Recipe&quot;">​</a></h3><ol><li>Move the generated <code>.patch</code> file into your recipe&#39;s <code>files/</code> subdirectory.</li><li>Edit your recipe <code>.bb</code> file to add the patch to the <code>SRC_URI</code>.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In your recipe.bb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file://helloworld.c </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">           file://0001-Change-greeting-text.patch </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          &quot;</span></span></code></pre></div><h3 id="how-the-do-patch-task-works" tabindex="-1">How the <code>do_patch</code> Task Works <a class="header-anchor" href="#how-the-do-patch-task-works" aria-label="Permalink to &quot;How the \`do_patch\` Task Works&quot;">​</a></h3><ol><li>BitBake runs <code>do_unpack</code>, placing the pristine <code>helloworld.c</code> into <code>\${WORKDIR}</code>.</li><li>BitBake runs <code>do_patch</code>. It sees a file ending in <code>.patch</code> in the <code>SRC_URI</code>.</li><li>It automatically uses the <code>patch</code> utility to apply <code>0001-Change-greeting-text.patch</code> against the source code.</li><li>BitBake proceeds to <code>do_compile</code> with the modified code.</li></ol><hr><h2 id="_3-hands-on-lab-exercises" tabindex="-1">3. Hands-On Lab Exercises <a class="header-anchor" href="#_3-hands-on-lab-exercises" aria-label="Permalink to &quot;3. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 10.1: Create and Apply a Patch</p><ol><li>Navigate to your <code>helloworld</code> recipe directory from Day 8.</li><li>Modify <code>helloworld.c</code> to change the printed text.</li><li>Use the <code>git format-patch</code> workflow described above to generate a <code>.patch</code> file.</li><li>Revert <code>helloworld.c</code> back to its original pristine state.</li><li>Add the <code>.patch</code> file to your <code>helloworld_1.0.bb</code> recipe&#39;s <code>SRC_URI</code>.</li><li>Run <code>bitbake -c clean helloworld &amp;&amp; bitbake helloworld</code>.</li><li>Boot QEMU and run <code>helloworld</code> to verify the patch was successfully applied during the build.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 10.2: Verifying the Patched Source</p><p>Want to prove the patch was applied correctly before building?</p><ol><li>Run <code>bitbake -c patch helloworld</code> (this stops execution right after the patch stage).</li><li>Navigate to <code>build/tmp/work/.../helloworld/1.0-r0/</code>.</li><li><code>cat helloworld.c</code> and verify that the file physically contains your patched modifications.</li></ol></div><hr><h2 id="_4-further-reading" tabindex="-1">4. Further Reading <a class="header-anchor" href="#_4-further-reading" aria-label="Permalink to &quot;4. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Fetchers Reference (Git)</td><td><a href="https://docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-fetching.html#git-fetcher-git" target="_blank" rel="noreferrer">docs.yoctoproject.org/bitbake/bitbake-user-manual/bitbake-user-manual-fetching.html#git-fetcher-git</a></td></tr><tr><td>Patching Source Code</td><td><a href="https://docs.yoctoproject.org/dev-manual/new-recipe.html#patching-code" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/new-recipe.html#patching-code</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day9-build-logs-debugging-makefiles">← Day 9: Build Logs &amp; Makefiles</a><a href="/day11-package-splitting-and-installed-vs-shipped">Day 11: Package Splitting →</a></div>`,37)])])}const g=i(o,[["render",l]]);export{k as __pageData,g as default};
